fn scripts(&mut self, base: Vec<Node>) -> Node {
    let (mut sub, mut sup) = (None, None);
    loop {
        match self.peek() {
            Some(Token::Sub) if sub.is_none() => {
                self.at += 1;
                sub = Some(self.argument());
